            "solution": "<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Validation\\Unified;\n\n/**\n * Unified validation runner — holes: type_coercion, message_localization, ruleset_composition\n */\nclass ValidationRunner\n{\n    public function validate(mixed $value, array $rules): array\n    {\n        // HOLE: type_coercion — should coerce types before validating (e.g., string to int)\n\n        $errors = [];\n\n        foreach ($rules as $rule) {\n            $ruleName = $rule['name'] ?? 'unknown';\n            $ruleParams = $rule['params'] ?? [];\n\n            if (!$this->checkRule($value, $ruleName, $ruleParams)) {\n                // HOLE: message_localization — message should use _('') for gettext\n                $errors[] = \"Validation failed for rule: {$ruleName}\";\n            }\n        }\n\n        return $errors;\n    }\n\n    private function checkRule(mixed $value, string $ruleName, array $params): bool\n    {\n        // HOLE: ruleset_composition — no support for 'when', 'allOf', 'anyOf' compositions\n\n        return match ($ruleName) {\n            'required' => $value !== null && $value !== '',\n            'min_length' => is_string($value) && strlen($value) >= ($params[0] ?? 0),\n            'max_length' => is_string($value) && strlen($value) <= ($params[0] ?? PHP_INT_MAX),\n            'nume